// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 burnValue) internal {
        uint256 beforeSupply;
        try c.totalSupply() returns (uint256 __r) { beforeSupply = __r; } catch { return; }
        bool reverted;
        try c.burn(burnValue) { reverted = false; } catch { reverted = true; }
        uint256 afterSupply;
        try c.totalSupply() returns (uint256 __r) { afterSupply = __r; } catch { return; }
        assertTrue(reverted ? afterSupply == beforeSupply : afterSupply + burnValue == beforeSupply);
    }

    function testFuzz_run(uint256 burnValue) public {
        _run(burnValue);
    }

    receive() external payable {}
}
